package main

import (
	"context"
	"fmt"
	"os"
	"strings"
	"time"

	"github.com/urfave/cli/v3"

	"github.com/livekit/protocol/logger"
	lksdk "github.com/livekit/server-sdk-go/v2"
)

func parseAllowedUsers(flagValue string) []string {
	if flagValue == "" {
		return nil
	}
	var users []string
	for _, u := range strings.Split(flagValue, ",") {
		if u = strings.TrimSpace(u); u != "" {
			users = append(users, u)
		}
	}
	return users
}

func main() {
	cmd := &cli.Command{
		Name:      "gstreamer-publisher",
		Usage:     "Publish video/audio from a GStreamer pipeline to LiveKit",
		Version:   "0.1.0",
		UsageText: "gstreamer-publisher --url <url> --token <token> [--delay second] -- <gst-launch parameters>",
		Flags: []cli.Flag{
			&cli.StringFlag{
				Name:    "url",
				Usage:   "url to LiveKit instance",
				Sources: cli.EnvVars("LIVEKIT_URL"),
				Value:   "http://localhost:7880",
			},
			&cli.IntFlag{
				Name:  "delay",
				Usage: "delay in seconds before publishing",
			},
			&cli.StringFlag{
				Name:     "token",
				Usage:    "access token for authentication. canPublish permission is required",
				Required: true,
			},
			&cli.StringFlag{
				Name:  "allowed-users",
				Usage: "comma-separated LiveKit participant identities allowed to subscribe to published tracks",
			},
			&cli.BoolFlag{
				Name: "verbose",
			},
		},
		Action: func(_ context.Context, c *cli.Command) error {
			publisher := NewPublisher(PublisherParams{
				URL:            c.String("url"),
				Token:          c.String("token"),
				PipelineString: strings.Join(c.Args().Slice(), " "),
				AllowedUsers:   parseAllowedUsers(c.String("allowed-users")),
			})
			if delay := c.Int("delay"); delay != 0 {
				time.Sleep(time.Duration(delay) * time.Second)
			}
			return publisher.Start()
		},
	}

	logger.InitFromConfig(&logger.Config{Level: "info"}, "gstreamer-publisher")
	lksdk.SetLogger(logger.GetLogger())
	if err := cmd.Run(context.Background(), os.Args); err != nil {
		fmt.Println(err)
		os.Exit(1)
	}
}

